	activity_infinite_speed = {
		id = "activity_infinite_speed",
		title = "无尽竞速说明",
		text = "<p>竞速规则说明：</p><p>【无尽竞速】挑战开启</p><p>◇规则说明：</p><p>◇总共若干个挑战，每个挑战玩家将面临一定数量的考核。</p><p>挑战开始会给班长们30s的初始时间，每完成一次考核会增加相应的奖励时间。</p><p>◇考核将有两种得分规则，规则一：在规定时间内击杀当前考核boss，获取当前考核难度奖励分。规则二：未能在规定时间内击杀当前考核boss，则根据对boss造成伤害的百分比获取奖励分。</p><p>◇每个挑战的不同考核难度有相应的考核难度奖励分，当班长结束挑战时，累计获得的考核难度奖励分即当前挑战获得总分。</p><p>◇部分学员拥有分数加成，结算时总分=获取分*110%，但是如果挑战队伍中存在多名特殊学员，结算分数加成只会生效一次。</p><p>◇已通关的考核可随时重复挑战，来获取更高的通关分数。最终得分以获取的最高挑战分为准。</p><p>◇试炼总得分为所有挑战获得的最高得分总和</p><p>◇试炼总得分可以帮助班长们在活动期间获取相应的积分奖励，积分奖励只能领取一次。</p><p><br/></p>"
