	Activity_Collect_154 = {
		id = "Activity_Collect_154",
		title = "海底捞月",
		text = "<p>【活动规则说明】</p><p>1、本活动共持续2期。</p><p>1期持续时间：21年1.28~2.11 23:59</p><p>2期持续时间：21年2.12~3.14 23:59</p><p><br/></p><p>2、活动期间内，新春麻将牌可以通过签到、分享、每日探险、新春翻牌等活动获得，并可以在集字活动主页中兑换丰厚奖励。</p><p><br/></p><p>3、部分奖励有兑换次数上限，到达上限后将不能再次兑换。</p><p><br/></p><p>4、本<span style=color:>活动结束后，新春麻将牌将不能兑换任何道具，请各位班长及时兑换</span>。</p><p><br/></p>"
