	ActivityMain_228 = {
		id = "ActivityMain_228",
		title = "角色上新说明",
		text = "<p>为了欢迎织弦舞者·织夜进入，学院将举办以下入学仪式</p><p><br/></p><p>活动持续时间：</p><p>2021.11.25更新后~12.19 23:59</p><p><br/></p><p>1、【新学员入学】</p><p>电磁、光能双属性学员【织弦舞者】织夜正式入学。</p><p>※前50抽内必定会获得【织弦舞者】织夜，班长快来邀请她加入班级吧~</p><p><br/></p><p>2、【每日探险】</p><p>织夜每日探险开启，班长通关将获得原型姬、学员礼物和猫猫币等道具，更有和学员相关剧情等待班长了解。</p><p><br/></p><p>3、【每日挑战】</p><p>每日挑战关卡开启，携带织夜挑战将事半功倍哦，完成挑战即可获得猫猫币、元素材料福利。</p><p><br/></p><p>4、【新学员支援】</p><p>新学员支援限时开启，参与活动可免费获得专属扭蛋券、科技箱、钞票箱等道具。</p><p>解锁特殊支援，玩家更可以获得更多的专属扭蛋券、科技箱、钞票箱等道具。</p><p><br/></p><p>5、【角色回礼】</p><p>角色回礼限时开启，班长在织夜蛋池中抽取一定次数，将能获得专属扭蛋券道具。</p><p><br/></p><p>6、【上新礼包】</p><p>织夜上新礼包限时开启，特价礼包限时售卖，内含礼品卡、扭蛋券等超值商品，班长可以前往购买。</p><p><br/></p>"
	},
	Activity_bp_228 = {
		id = "Activity_bp_228",
		title = "新学员支援",
		text = "<p>「新学员支援」活动说明：</p><p><br/></p><p>◇活动时间：2021.11.25更新后~12.19 23:59</p><p><br/></p><p>◇班长可以通过购买特殊支援来解锁特殊补给线。</p><p><br/></p><p>◇特殊支援线分为两档：典藏档位相比普通档位可以额外获得专属扭蛋券、超凡学员证元件和1000支援点。</p><p><br/></p><p>◇班长在解锁特殊支援后会开启快速提升功能，班长可以消耗魂晶来快速提升等级。</p><p><br/></p><p>◇普通档位的班长可以通过快速提升界面右上角来升级成典藏版，并只需要补齐差价即可。</p><p><br/></p><p>◇班长可以通过完成对应的任务来获得相应的奖励。</p><p><br/></p><p>◇累计奖励中的支援点可以提升活动支援的等级</p><p><br/></p><p>◇每提升一级，班长就可以获得对应等级的奖励。</p>"
