	Activity_bp_272 = {
		id = "Activity_bp_272",
		title = "超频支援",
		text = "<p>「超频支援」活动说明：</p><p><br/></p><p>◇活动时间：2022.04.14~2022.05.04 </p><p><br/></p><p>◇班长可以通过购买特殊支援来解锁特殊补给线</p><p><br/></p><p>◇特殊支援线分为两档：典藏档位相比普通档位可以额外获得10个独特学员证元件、2个超频处理器以及1000支援点</p><p><br/></p><p>◇班长在解锁特殊支援后会开启快速提升功能，班长可以消耗魂晶来快速提升等级</p><p><br/></p><p>◇普通档位的班长可以通过快速提升界面右上角来升级成典藏版，并只需要补齐差价即可</p><p><br/></p><p>◇班长可以通过完成对应的任务来获得相应的奖励</p><p><br/></p><p>◇累计奖励中的支援点可以提升活动支援的等级</p><p><br/></p><p>◇每提升一级，班长就可以获得对应等级的奖励</p>"
	},
	ActivityMain_279 = {
		id = "ActivityMain_279",
		title = "角色上新说明",
		text = "<p>为了欢迎破境青鸿·千竹进入，学院将举办以下入学仪式</p><p><br/></p><p>活动持续时间：</p><p>2022.04.19更新后~2022.05.22 23:59</p><p><br/></p><p>1、【新学员入学】</p><p>来自派森的冒失女孩，在魂器学院经历了种种之后，终于迎来了新的蜕变，独特正能量属性学员【破境青鸿】千竹正式登场。</p><p><br/></p><p>2、【每日探险】</p><p>每日探险开启，班长通关将获得原型姬、学员礼物和青雨硬币等道具，更有和学员相关剧情等待班长了解。</p><p><br/></p><p>3、【每日挑战】</p><p>每日挑战关卡开启，携带破境青鸿·千竹挑战将事半功倍哦，完成挑战即可获得青雨硬币、元素材料福利。每日可挑战3次。</p><p><br/></p><p>4、【新学员支援】</p><p>新学员支援限时开启，参与活动可免费获得专属扭蛋券、科技箱、钞票箱等道具。</p><p>解锁特殊支援，玩家更可以获得更多的专属扭蛋券、科技箱、钞票箱等道具。</p><p><br/></p><p>5、【累抽奖励】</p><p>角色回礼限时开启，班长在破境青鸿蛋池中抽取一定次数，将能获得专属扭蛋券等道具。</p><p><br/></p><p>6、【角色礼包】</p><p>破境青鸿上新礼包限时开启，特价礼包限时售卖，内含礼品卡、扭蛋券等超值商品，班长可以前往购买。</p><p><br/></p><p>7、【领主挑战】</p><p>和强力的领主进行挑战，获得专属扭蛋券、星原型机、进修卡等丰厚奖励。</p><p>8、【兑换商城】</p><p>在活动中获得的青雨硬币，可以在兑换商店中兑换丰厚奖励。完成兑换商店任务也可以获得青雨硬币。青雨硬币将会在活动到期后清除，请尽快使用。</p>"
	},
	Activity_bp_279 = {
		id = "Activity_bp_279",
		title = "新学员支援",
		text = "<p>「新学员支援」活动说明：</p><p><br/></p><p>◇活动时间：2022.04.19更新后~2022.05.22 23:59</p><p><br/></p><p>◇班长可以通过购买特殊支援来解锁特殊补给线。</p><p><br/></p><p>◇特殊支援线分为两档：典藏档位相比普通档位可以额外获得专属扭蛋券、独特学员证元件和1000支援点。</p><p><br/></p><p>◇班长在解锁特殊支援后会开启快速提升功能，班长可以消耗魂晶来快速提升等级。</p><p><br/></p><p>◇普通档位的班长可以通过快速提升界面右上角来升级成典藏版，并只需要补齐差价即可。</p><p><br/></p><p>◇班长可以通过完成对应的任务来获得相应的奖励。</p><p><br/></p><p>◇累计奖励中的支援点可以提升活动支援的等级</p><p><br/></p><p>◇每提升一级，班长就可以获得对应等级的奖励。</p>"
