	ActivityLevel_404 = {
		id = "ActivityLevel_404",
		title = "「每日挑战」说明",
		text = "<p>【每日挑战】开启！<br/></p><p>活动时间：2022.10.22更新后~2022.11.30 23:59</p><p>规则说明<br/></p><p>◇开启规则开启规则</p><p>每日本共7关，后续关卡需打过上个关卡解锁。</p><p>◇次数规则</p><p><strong>每天</strong>将会发<strong>3次</strong>每日本次数，每天挑战的数量不会保存。</p><p>首次通关每日本不消耗次数。</p><p>◇奖励</p><p>每日本每次通关后将获得联动积分、联动好感礼物、钞票箱。</p><p>不同难度每日本的联动积分掉落相同，上阵头号玩家·嗒啦啦将获得额外联动积分。</p><p>随着头号玩家·嗒啦啦共振次数的提高，额外获得的联动积分的数量也会增加。</p><p>角色<strong>0/1/2/3/4/5振</strong>时，额外获得的联动积分各数量增加<strong>100/120/150/200/250/300</strong>。</p><p>每日本可额外花费魂晶购买一次挑战次数。</p><p><br/></p>"
