	Activity_guard_722 = {
		id = "Activity_guard_722",
		title = "「沙滩保卫战」说明",
		text = "<p>【沙滩保卫战】规则说明<br/></p><p>通过交换两个相邻的道具，凑成三个连续横排或者竖排，从而合成保卫装置，来保护沙滩城堡，撑过更多的天数，获得更高的积分。<br/></p><p><br/></p><p>白天状态时，玩家可以通过交换相邻道具来移动，每交换一次会消耗1点行动点数，每个白天拥有固定的行动点数，行动点数消耗完毕后进入夜晚保卫，海鸥会从下方随机进攻，没有及时击落海鸥时，每一只海鸥会减少城堡的1点生命。<br/></p><p><br/></p><p>道具种类：<br/></p><p>西瓜：三个西瓜合成可以攻击整个竖排的炮塔，3个相同等级的炮塔可以合成更高等级的炮塔。<br/></p><p>汽水：三个汽水合成可以攻击整个横排的炮塔，3个相同等级的炮塔可以合成更高等级的炮塔。<br/></p><p>沙堆：三个沙堆合成可以攻击周围9格范围的箭塔，3个相同等级的箭塔可以合成更高等级的箭塔。<br/></p><p>贝壳：三个贝壳可以合成城墙，城墙会降低海鸥在该格的移动速度，3个相同等级的城墙可以合成更高等级的城墙。<br/></p><p>金币：三个金币可以合成宝箱，点击宝箱可以获得额外的行动点数，3个相同等级的宝箱可以合成更高等级的宝箱。<br/></p><p><br/></p><p><br/></p><p>每过10天，巨大的海鸥会前来进攻，当巨大海鸥被击落时，会生成许多小海鸥，请务必警惕。<br/></p>"
	},
	SummerFarm = {
		id = "SummerFarm",
		title = "「沙滩农场」说明",
		text = "<p>【沙滩农场】规则说明<br/></p><p>通过根据订单需求的水果数量，种植对应的水果，在订单时间限制内完成订单，获得更高的积分。<br/></p><p><br/></p><p>玩家可以通过拖动下方的水果种植在12格土地上，每个水果的收获时间都显示在上方。种植水果需要会消耗【1】个时间单位。每过【1】个时间单位，农场里的水果都会成长一次，水果成长完成时可以收获，收获不消耗时间。<br/></p><p><br/></p><p>玩家可以点击为成长完成的水果进行浇水，浇水会消耗【1】个时间单位，并且使该植物额外成长一次。<br/></p><p>每次收获水果，都会获得1点水果经验，水果经验到达一定数值会使水果升级，升级后的水果在收获时的产量会更多。<br/></p><p><br/></p><p>玩家需要在剩余时间内完成订单，即可获得积分然后获得下一个订单，未用完的剩余时间会转化成所有水果经验。如果剩余时间为0时，订单需求没有满足则订单失败，该次游戏结束。<br/></p><p><br/></p><p>沙滩农场上可以种植【4】种水果，每种水果都有不同的特性：<br/></p><p>西瓜：升级后生长时间会提高，并且产量显著提高。<br/></p><p>草莓：每次收获时有几率获得双倍产量，升级后几率提高<br/></p><p>葡萄：葡萄在收获后会自动在原位播种。<br/></p><p>菠萝：每次浇水会使周围【4】格的水果也额外成长一次。<br/></p><p><br/></p><p>玩家可以使用铲除功能，将不需要的水果铲除，铲除不会消耗时间。<br/></p>"
	},
	ActivityGrouptower_722 = {
		id = "ActivityGrouptower_722",
		title = "[联合作战爬塔]",
		text = "<p>欢迎来到「联合作战爬塔」，以下是活动规则：</p><p><br/></p><p>1、「联合作战爬塔」共100层。</p><p><br/></p><p>2、前50层玩家需要上阵2队学员进行挑战，后50层需要上阵3队学员进行挑战。</p><p><br/></p><p>3、击败关卡内所有编队的敌人才视作通关成功。</p>"
