	ActivityBakery_775 = {
		id = "ActivityBakery_775",
		title = "「新春蛋糕店」说明",
		text = "<p>欢迎来到「新春蛋糕店」，以下是活动规则：</p><p><br/></p><p>1、新春蛋糕店总共有30个关卡，每次经营需要消耗1张经营许可证，经营许可证每2小时获得1个，最多保存5个。</p><p><br/></p><p>2、经营开始时，根据客人订单需求制作对应的蛋糕、奶茶和芋圆。</p><p><br/></p><p>点击烤箱进行烘培，烘烤完成时进入保温状态，没有及时点击蛋糕胚放到托盘上会导致烤糊，需要点击清理才能再次制作。</p><p><br/></p><p>点击三种奶油中的一种会给蛋糕胚涂上奶油。</p><p><br/></p><p>点击右下角的水果箱会切对应的水果，切完后会放到水果盘上，点击水果盘上的水果会在蛋糕胚上放水果，一个蛋糕只能放置一种水果。</p><p><br/></p><p>点击可以符合订单的蛋糕就可以提交蛋糕，连续点击两次可以将蛋糕清理。</p><p><br/></p><p>若干关卡后开放奶茶制作，点击奶茶机会自动制作奶茶。点击珍珠碗可以为奶茶里增加珍珠。</p><p><br/></p><p>若干关卡后开放芋圆制作，点击芋圆碗会自动制作芋圆。点击小料可以为奶茶里增加红豆或者芒果，芋圆最多可以<p><br/></p><p>4、获得的营业额金币可以在右下角进行蛋糕店设备升级，增加效率。</p>放置两种小料。</p><p><br/></p><p>3、完成经营目标的营业额则完成挑战，进入下一关。挑战失败同样可以获得对应的营业额金币。</p><p><br/></p><p>5、完成关卡获得满意桃花可以在活动商城兑换道具。</p>"
	},
	worldboss_775 = {
		id = "worldboss_775",
		title = "「守岁试炼」说明",
		text = "<p>欢迎来到「守岁试炼」，以下是活动规则：</p><p><br/></p><p>1、玩家每日有3次挑战次数进行守岁试炼挑战，守岁试炼分为3个阶段：小怪阶段、精英怪阶段和boss阶段。</p><p><br/></p><p>2、小怪阶段会出现2个敌人，玩家可以挑战任意敌人，每次成功挑战会消耗挑战次数，并且获得角色攻击力或者血量加成，加成仅作用于守岁试炼。</p><p><br/></p><p>每个小怪阶段持续两天，两天后进入精英怪阶段。</p><p><br/></p><p>3、精英怪阶段会出现一个强大的敌人，挑战成功会消耗挑战次数。</p><p><br/></p><p>每个精英怪阶段持续两天，两天后进入boss阶段。</p><p><br/></p><p>4、boss阶段会出现一个特别强大的敌人，玩家通过参与挑战对boss造成伤害，获得参与奖励，参与挑战会消耗挑战次数，并且获得攻击力和血量加成。</p><p><br/></p><p>玩家参与的挑战的最高伤害会记录，并且加入排行榜。boss挑战完成时会根据玩家伤害排名给予奖励。</p><p><br/></p><p>5、boss被击败后，第二天会重新进入小怪阶段，依次循环。<p><br/></p><p>6、上阵特定学员可以获得特殊状态加成。</p>"
